effect.shader:
const int MARGEM = 256;            // = margin dos buffers
const float RAIO_A = 1.6633;       // R = RAIO_B + RAIO_A · Softness (medido: r2_32, r3_32, r4_16)
const float RAIO_B = 1.0019;
const float GRAUS = 0.017453292519943295;

float escala() { return acEscalaDePixel > 0.0 ? acEscalaDePixel : 1.0; }

// O deslocamento em px do buffer, y para baixo como no AE; com a cena de pé (a linha 0 é a base), o "para baixo" é
// para cima aqui.
vec2 deslocamento() {
    float d = shadowDistance * escala();
    float t = shadowAngle * GRAUS;
    vec2 v = vec2(sin(t), -cos(t)) * d;
    return vec2(v.x, acEntradaDePe == 1 ? -v.y : v.y);
}

// O alfa da camada; fora do quadro, transparente.
float alfaDaCamada(ivec2 c) {
    ivec2 t = textureSize(inputImg, 0);
    if (any(lessThan(c, ivec2(0))) || any(greaterThanEqual(c, t))) return 0.0;
    return texelFetch(inputImg, c, 0).a;
}

// 24 bits fixos no RGB de um RGBA8 (o alfa da passada fica em [0, 1]).
vec4 guardar(float v) {
    uint q = min(uint(clamp(v, 0.0, 1.0) * 16777216.0), 16777215u);
    return vec4(float(q >> 16u), float((q >> 8u) & 255u), float(q & 255u), 255.0) / 255.0;
}
float abrir(sampler2D b, ivec2 c) {
    ivec2 p = c + MARGEM;
    ivec2 n = textureSize(b, 0);
    if (any(lessThan(p, ivec2(0))) || any(greaterThanEqual(p, n))) return 0.0;
    uvec3 k = uvec3(floor(texelFetch(b, p, 0).rgb * 255.0 + 0.5));
    return float((k.x << 16u) | (k.y << 8u) | k.z) / 16777216.0;
}

void main() {
    if (acPass == 0) {
        // a máscara: o alfa em (c − deslocamento), bilinear
        vec2 p = vec2(ivec2(gl_FragCoord.xy) - MARGEM) - deslocamento();
        vec2 b = floor(p);
        vec2 f = p - b;
        ivec2 i = ivec2(b);
        float m = mix(mix(alfaDaCamada(i), alfaDaCamada(i + ivec2(1, 0)), f.x),
                      mix(alfaDaCamada(i + ivec2(0, 1)), alfaDaCamada(i + ivec2(1, 1)), f.x), f.y);
        fragColor = guardar(m);
        return;
    }

    if (acPass < 3) {
        // o triângulo do Pyramid: horizontal no passe 1 (lê dsA), vertical no 2 (lê dsB)
        ivec2 c = ivec2(gl_FragCoord.xy) - MARGEM;
        ivec2 eixo = acPass == 1 ? ivec2(1, 0) : ivec2(0, 1);
        float R = (RAIO_B + RAIO_A * shadowSoftness) * escala();
        int n = int(ceil(R)) - 1;
        float S = float(2 * n + 1) * R - float(n * (n + 1));
        float soma = 0.0;
        for (int k = -n; k <= n; k++) {
            float w = R - float(abs(k));
            soma += w * (acPass == 1 ? abrir(dsA, c + eixo * k) : abrir(dsB, c + eixo * k));
        }
        fragColor = guardar(soma / S);
        return;
    }

    // A composição em 8 bits, como o AE (medido: r1_8 e r4_8, o alfa a até 1 nível com alfa parcial): o gamma em
    // float, a máscara arredondada a 8 bits, Intensity em 1/256, a sombra e a soma truncadas. O 1e-4 segura o
    // inteiro exato que a divisão da GPU devolve um tico abaixo.
    ivec2 c = ivec2(gl_FragCoord.xy);
    float m = clamp(abrir(dsA, c), 0.0, 1.0);
    float g = max(gamma, 0.001);
    float m8 = floor(255.0 * pow(m, 1.0 / g) + 0.5);
    float i8 = floor(clamp(shadowIntensity, 0.0, 1.0) * 256.0 + 0.5) / 256.0;
    float s8 = floor(m8 * i8 + 1e-4);
    vec3 cor = shadowColor.rgb;

    // a camada (reta) × Source Opacity por cima da sombra
    vec4 l = texelFetch(inputImg, c, 0);
    float l8 = floor(floor(l.a * 255.0 + 0.5) * clamp(sourceOpacity, 0.0, 1.0) + 1e-4);
    float a8 = floor(l8 + s8 * (255.0 - l8) / 255.0 + 1e-4);
    vec4 saida = a8 > 0.0 ? vec4((l.rgb * l8 + cor * (a8 - l8)) / a8, a8 / 255.0) : vec4(0.0);
    if (l8 == 0.0 && a8 > 0.0) saida.rgb = cor;
    fragColor = clamp(saida, 0.0, 1.0);
}
